import { defineConfig } from "oxfmt";
import ultracite from "ultracite/oxfmt";

// Ultracite's formatting defaults, with nothing ported over from the previous
// project (Q8b). The additions below are files that are not ours to reformat.
export default defineConfig({
  ...ultracite,
  ignorePatterns: [
    ...ultracite.ignorePatterns,
    // Vendored third-party scripts, checked in exactly as they ship.
    "src/plugins/performance-improvement/scripts/**/*.js",
    // Generated by `pnpm changelog`.
    "changelog.md",
    // Prose we hand-maintain: reformatting only rewraps paragraphs, and the PRD's
    // line breaks are what keeps its diffs reviewable.
    "README.md",
    "docs/**",
  ],
});
